import math

state = 'unpin'
unpin_start_t = None

def control(obs):
    global state, unpin_start_t
    t = obs['t']
    hitch = obs['hitch_deg']
    look_target = -23.0
    cam = obs.get('views', {}).get('camera', None)

    if state == 'unpin':
        if unpin_start_t is None:
            if obs['motion']['hold_s'] <= 0.05:
                unpin_start_t = t
            return {'steer_deg': -25.0, 'speed_mps': 1.0, 'look_deg': look_target}

        if t - unpin_start_t < 1.8:
            return {'steer_deg': -20.0, 'speed_mps': 1.0, 'look_deg': look_target}
        else:
            state = 'reverse'

    target_hitch = 0.0

    if cam and 'walls' in cam and len(cam['walls']) > 0:
        axis = cam['axis_deg']
        left_pts = []
        right_pts = []

        for b, d in cam['walls']:
            rel = b - axis
            while rel > 180: rel -= 360
            while rel < -180: rel += 360
            lat = d * math.sin(math.radians(rel))
            long_d = d * math.cos(math.radians(rel))

            if long_d > -0.5:
                if lat > 0:
                    left_pts.append((long_d, lat))
                else:
                    right_pts.append((long_d, -lat))

        target = obs.get('target', {})
        if target.get('in_sight') and target.get('bearing_deg') is not None:
            tb = target['bearing_deg']
            rel_t = tb - axis
            while rel_t > 180: rel_t -= 360
            while rel_t < -180: rel_t += 360
            target_hitch = max(-25.0, min(25.0, 0.8 * rel_t))
        else:
            bend_angles = []
            for b, d in cam['walls']:
                if d > 2.0:
                    rel = b - axis
                    while rel > 180: rel -= 360
                    while rel < -180: rel += 360
                    bend_angles.append(rel)

            if bend_angles:
                avg_bend = sum(bend_angles) / len(bend_angles)
                target_hitch = max(-22.0, min(22.0, 0.6 * avg_bend))

            for d_long, d_lat in left_pts:
                if d_lat < 1.1 and d_long < 2.0:
                    target_hitch = min(target_hitch, -15.0)
            for d_long, d_lat in right_pts:
                if d_lat < 1.1 and d_long < 2.0:
                    target_hitch = max(target_hitch, 15.0)

    hitch_err = hitch - target_hitch
    steer = 2.0 * hitch_err
    steer = max(-34.0, min(34.0, steer))

    return {'steer_deg': steer, 'speed_mps': -0.9, 'look_deg': look_target}

