import math

class Controller:
    def __init__(self):
        self.state = 'UNPIN_FWD'
        self.fwd_start_t = None

ctrl = Controller()

def control(obs):
    t = obs['t']
    hitch = obs['hitch_deg']
    hold = obs['motion']['hold_s']
    look = -23.0
    cam = obs.get('views', {}).get('camera')
    prog = obs['progress']['covered']

    # Phase 1: Wait out penalty and pull forward ~5-6 meters with right steering to pull trailer away from left rail
    if ctrl.state == 'UNPIN_FWD':
        if hold > 0:
            return {'steer_deg': -20.0, 'speed_mps': 1.5, 'look_deg': look}
        if ctrl.fwd_start_t is None:
            ctrl.fwd_start_t = t

        # Pull forward for 5.0 seconds
        if t - ctrl.fwd_start_t < 5.0:
            return {'steer_deg': -20.0, 'speed_mps': 1.5, 'look_deg': look}
        else:
            ctrl.state = 'REVERSE'

    # Phase 2: Reverse along the bend
    target_hitch = -12.0

    if cam and 'walls' in cam and len(cam['walls']) > 0:
        axis = cam['axis_deg']
        min_left = 999.0
        min_right = 999.0
        for b, d in cam['walls']:
            rel = b - axis
            while rel > 180: rel -= 360
            while rel < -180: rel += 360
            lat = d * math.sin(math.radians(rel))
            long_d = d * math.cos(math.radians(rel))
            if long_d > -0.3:
                if rel > 0 and lat < min_left:
                    min_left = lat
                elif rel < 0 and (-lat) < min_right:
                    min_right = -lat

        if min_left < 1.15:
            target_hitch = -20.0
        elif min_right < 1.15:
            target_hitch = -4.0
        elif min_left < 900 and min_right < 900:
            diff = min_left - min_right
            target_hitch = -12.0 - diff * 12.0
            target_hitch = max(-22.0, min(-3.0, target_hitch))

    if prog > 23.5:
        remaining_ratio = max(0.0, (26.1 - prog) / 2.6)
        target_hitch = target_hitch * remaining_ratio

    hitch_err = hitch - target_hitch
    steer = 2.2 * hitch_err
    steer = max(-34.0, min(34.0, steer))

    return {'steer_deg': steer, 'speed_mps': -0.75, 'look_deg': look}

