        else:
            ctrl.state = 'REVERSE'

    # Phase 2: Reverse into bay
    target_hitch = -35.0
    if cam:
        corners = cam.get('target_corners', [])
        if corners and len(corners) >= 2:
            avg_b = sum(b for b, d in corners) / len(corners)
            err = avg_b - cam['axis_deg']
            while err > 180: err -= 360
            while err < -180: err += 360
            target_hitch = hitch - 0.7 * err
        elif cam.get('walls'):
            axis = cam['axis_deg']
            min_l = 999.0
            min_r = 999.0
            for b, d in cam['walls']:
                rel = b - axis
                while rel > 180: rel -= 360
                while rel < -180: rel += 360
                lat = d * math.sin(math.radians(rel))
                long_d = d * math.cos(math.radians(rel))
                if long_d > -0.2:
                    if rel > 0 and lat < min_l:
                        min_l = lat
                    elif rel < 0 and (-lat) < min_r:
                        min_r = -lat
            if min_l < 1.2:
                target_hitch = min(hitch - 5.0, -45.0)
            elif min_r < 1.2:
                target_hitch = max(hitch + 8.0, -20.0)
            else:
                target_hitch = -35.0

