import math

phase = 0
start_cov = None

def control(obs):
    global phase, start_cov

    hitch = obs.get('hitch_deg', 0.0)
    cov = obs.get('progress', {}).get('covered', 0.0)
    look_deg = 145.0

    # Phase 0: Pull forward 1.2 meters, steer slightly left (+10 deg) to shift vehicle & trailer away from right wall
    if phase == 0:
        if start_cov is None:
            start_cov = cov
        if cov <= start_cov - 1.2:
            phase = 1
        return {'steer_deg': 10.0, 'speed_mps': 0.4, 'look_deg': 145.0}

    # Phase 1: Reversing towards the bay
    v_target = -0.22

    views = obs.get('views', {})
    left_y = []
    right_y = []

    for vname, vdata in views.items():
        ox, oy = vdata.get('origin', [0, 0])
        for pt in vdata.get('walls', []):
            rad = math.radians(pt[0])
            px = ox + pt[1] * math.cos(rad)
            py = oy + pt[1] * math.sin(rad)
            if px < 0.2:
                if py > 0:
                    left_y.append(py)
                else:
                    right_y.append(abs(py))

    target_hitch = 0.0
    if right_y:
        min_r = min(right_y)
        if min_r < 0.85:
            target_hitch = min(8.0, (0.85 - min_r) * 20.0)
    if left_y:
        min_l = min(left_y)
        if min_l < 0.75:
            target_hitch = max(-8.0, -(0.75 - min_l) * 20.0)

    hitch_err = hitch - target_hitch
    steer_deg = max(-25.0, min(25.0, 2.2 * hitch_err))

    return {'steer_deg': steer_deg, 'speed_mps': v_target, 'look_deg': look_deg}

